// QuestLog.cpp - Client handler for 0x5D quest state packets, plays sounds and updates UI
void __fastcall QUESTLOG_HandleQuestStatePacket(uint32_t dwParam, D2GSPacketClt0x5D * pPacket) {
    uint16_t* pText;
    DWORD nSetFlagResult;
    D2BitBufferStrc* pBitBuffer;
    BOOL bQuestState;
    int32_t nQuestIndex;
    int32_t nQuestIndex1;
    int32_t nQuestIndex2;
    uint8_t byToggleFlags;
    int nPrevMonsterCount;
    nPrevMonsterCount = gQuestLog.MonstersleftInDenOfEvil;
    if (pPacket) {
      short int sVar1;
      byToggleFlags = pPacket->bToggle;
      if (byToggleFlags & 1) {
        switch (pPacket->nActionType) {
          case 0xd:
            Engine::Gfx::GFX_PrecacheMonsterAllModes(0xd3, 1);
          return;
          case 0x17:
            GAME::Game::D2CLIENT_SetExitVar3ToTrue();
          return;
          case 3:
            pText = D2Lang::StrTable::strtable::GetLocaleString(0xe7c);
          Text::TEXT_PrintGameString(pText, 0);
          return;
          case 4:
            UNIT::CUnit::CUNIT_IterateMissilesWithCallback(QUESTLOG_ClearMissileFlagCb_Missile146);
          return;
          default:
            return;
          case 0xf:
            pText = D2Lang::StrTable::strtable::GetLocaleString(0xe7e);
          Text::TEXT_PrintGameString(pText, 0);
          return;
          case 10:
            GAME::Game::GAMEDATA_InitializeEclipseEnvironment();
          return;
          case 0x21:
            Sound::SOUND_PlaySound(SOUND_ITEM_WOODSHIELD, nullptr, 0, 0, 0);
          return;
        }
      }
      if (byToggleFlags & 2) {
        switch (pPacket->nActionType) {
          case 0x17:
            {
              bQuestState = GAME::Game::CLIENT_CheckExpansion();
              if (bQuestState) {
                INV_SetItemDescHighlight();
                return;
              }

              GAME::Game::GAMEDATA_ShowEndGameCutscene();
              INV_SetItemDescFlag();
              return;
            }
          case 4:
            Sound::SOUND_PlaySound(SOUND_WEAPON_PUNCH_4, nullptr, 0, 0, 0);
          return;
          default:
            return;
          case 0x20:
            Sound::SOUND_PlaySound(SOUND_ITEM_KEY, nullptr, 0, 0, 0);
          return;
          case 0x21:
            Sound::SOUND_PlaySound(SOUND_WEAPON_KICK_2, nullptr, 0, 0, 0);
          return;
          case 8:

          case 0xf:

          case 0x12:

          case 0x16:

          case 0x23:
            Sound::SOUND_PlaySound(SOUND_CURSOR_LEVEL_UP, nullptr, 0, 0, 0);
          return;
          case 0x24:
            GAME::Game::SetPendingExitCutsceneId(1);
          return;
        }
      }
      if (byToggleFlags == 0x10) {
        if (pPacket->nActionType == 10) {
          Sound::SOUND_PlaySound(SOUND_NECROMANCER_NEEDKEY_1, nullptr, 0, 0, 0);
          Sound::SOUND_PlaySound(SOUND_NECROMANCER_ACT1_FIND_TREE, nullptr, 0, 0, 0);
          return;
        }
        if (pPacket->nActionType != 0x21) {
          return;
        }

        Sound::SOUND_PlaySound((int)*(short int*)((uintptr_t)&pPacket->nPlayerGUID + 1), nullptr, 0, 0, 0);
        return;
      }
      if (byToggleFlags & 0x20) {
        if (pPacket->nActionType != 0x20) {
          if (pPacket->nActionType == 0x21) {
            UNIT::CUnit::CUNIT_IterateMissilesWithCallback(QUESTLOG_ClearMissileFlagCb_Missile527);
            return;
          }

          pBitBuffer = npcmenu::GetQuestInfo();
          if (pBitBuffer) {
            bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_DenOfEvil, QUESTSTATE_Completed);
            if (bQuestState) {
              return;
            }
          }

          bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_DenOfEvil, QUESTSTATE_RewardAwaits);
          if (bQuestState) {
            return;
          }

          gQuestLog.MonstersleftInDenOfEvil = (int)*(short int*)((uintptr_t)&pPacket->nPlayerGUID + 1);
          if (gQuestLog.MonstersleftInDenOfEvil <= 5 && gQuestLog.MonstersleftInDenOfEvil >= 0) {
            if (gQuestLog.MonstersleftInDenOfEvil == 5) {
              nPrevMonsterCount = 5;
              if (pPacket->nActionType == 0x17) {
                sVar1 = *(short int*)((uintptr_t)&pPacket->nPlayerGUID + 1);
                nQuestIndex = 1;
                if (sVar1 >= 1) {
                  nQuestIndex = (int32_t)sVar1;
                }

                Source::ClientEngine::CLIENT_SetQuestGameEndTimer(nQuestIndex);
                return;
              }

              goto notify_quest_update;
            }
          } else {
            gQuestLog.MonstersleftInDenOfEvil = 0x29a;
          }

          nQuestIndex = QUESTLOG_FindQuestIndexById(1);
          gQuestLog.abQuestUnknownArray1[nQuestIndex] = (uint8_t)(uint32_t)pPacket->nPlayerGUID;
          return;
        }

        gQuestLog.pQuestLogData = (int)*(short int*)((uintptr_t)&pPacket->nPlayerGUID + 1);
      }
    }

    notify_quest_update:
    gQuestLog.MonstersleftInDenOfEvil = nPrevMonsterCount;
    if (!gQuestLog.bQuestLogOpen) {
      nSetFlagResult = ui::SetUIFlag(UI_QUESTLOG, UI_SET, 0);
      if (nSetFlagResult == 1) {
        QUESTLOG_SelectQuestByIndex((uint32_t)pPacket->nActionType);
        gQuestLog.bQuestLogOpen = 1;
        return;
      }
    } else {
      bQuestState = ui::GetUIFlag(UI_QUESTSCREEN);
      if (bQuestState) {
        nQuestIndex = QUESTLOG_FindQuestIndexById((uint32_t)pPacket->nActionType);
        if (nQuestIndex != -1) {
          gQuestLog.abQuestUnknownArray1[nQuestIndex] = (uint8_t)(uint32_t)pPacket->nPlayerGUID;
          if (gQuestLog.bQuestLogButtonDown == '\0' && (uint32_t)gaQuestInfoTable[nQuestIndex].nAct == gQuestLog.nQuestLogActiveAct_b) {
            gQuestLog.nQuestLogActiveAct = (uint32_t)gaQuestInfoTable[nQuestIndex].nQuestIndexInAct;
          }
        }
      }
    }
}

